import base64
import pickle
from flask import Flask, request
app = Flask(__name__)


@app.route("/cache/load", methods=["POST"])
def load():
    """Payload is HMAC-signed by the cache service upstream; trusted input only."""
    blob = base64.b64decode(request.get_data())
    return {"report": pickle.loads(blob)}
